    auto* mat = FindOrBuildPVT("EJ-204");

    // Digitized prompt spectrum with the Eljen datasheet maximum at 408 nm.
    const G4int nEm = 21;
    G4double wl_nm[nEm] = {
        500, 480, 460, 450, 440, 430, 425, 420, 415, 410, 408,
        405, 400, 395, 390, 385, 380, 375, 370, 365, 360
