    G4double photonE[nEm], spectrum[nEm];
    BuildSpectrum(wl_nm, relOut, nEm, photonE, spectrum);
    AddScintillatorProperties(
        mat, photonE, spectrum, nEm, 380.0 * cm, 425.0 * nm,
        10000.0 / MeV, 0.9 * ns, 2.1 * ns);
    return mat;
}

