namespace Materials {

namespace {
G4Material* FindOrBuildPVT(const G4String& name, G4double density) {
    if (auto* existing = G4Material::GetMaterial(name, false)) {
        return existing;
    }

    auto* nist = G4NistManager::Instance();
    auto* carbon = nist->FindOrBuildElement("C");
    auto* hydrogen = nist->FindOrBuildElement("H");

    // Polyvinyltoluene repeat unit, consistent with Eljen EJ-230 base.
    auto* mat = new G4Material(name, density, 2);
    mat->AddElement(carbon, 9);
    mat->AddElement(hydrogen, 10);
    return mat;
}
} // namespace

// ---------------------------------------------------------------------------
G4Material* CreateEJ200() {
    auto* nist = G4NistManager::Instance();
    G4Material* mat = nist->FindOrBuildMaterial("G4_PLASTIC_SC_VINYLTOLUENE");

    // Espectro de emision del EJ-200 — digitalizado del datasheet de Eljen
    // Technology (figura "EJ-200 Emission Spectrum").
    //
    // El espectro cubre 380–500 nm con pico en 425 nm.  Se usaron 22 puntos
    // para capturar el pico estrecho y las colas con fidelidad suficiente.
    //
    // ORDEN: longitud de onda DESCENDENTE (equivale a energia ASCENDENTE),
    // como exige G4MaterialPropertiesTable para propiedades vectoriales.
    //
    // Valores de amplitud relativa leidos del grafico del datasheet:
    //   λ(nm) | amplitud
    //   500   | 0.010
    //   490   | 0.020
    //   480   | 0.050
    //   470   | 0.100
    //   465   | 0.145
    //   460   | 0.200
    //   455   | 0.280
    //   450   | 0.370
    //   445   | 0.460
    //   440   | 0.560
    //   435   | 0.680
    //   432   | 0.780
    //   430   | 0.860
    //   428   | 0.930
    //   426   | 0.980
    //   425   | 1.000   <- pico
    //   423   | 0.970
    //   420   | 0.880
    //   415   | 0.680
    //   410   | 0.460
    //   405   | 0.280
    //   400   | 0.150
    //   395   | 0.070
    //   390   | 0.030
    //   385   | 0.010
    //   380   | 0.002
    const G4int nEm = 26;
    G4double wl_nm[nEm]  = {500, 490, 480, 470, 465, 460, 455, 450, 445, 440,
                             435, 432, 430, 428, 426, 425, 423, 420, 415, 410,
                             405, 400, 395, 390, 385, 380};
    G4double relOut[nEm] = {0.010, 0.020, 0.050, 0.100, 0.145, 0.200, 0.280, 0.370,
                             0.460, 0.560, 0.680, 0.780, 0.860, 0.930, 0.980, 1.000,
                             0.970, 0.880, 0.680, 0.460, 0.280, 0.150, 0.070, 0.030,
                             0.010, 0.002};

    const G4double hc = 1239.84193 * eV * nm; // h·c in eV·nm

    // Convertir a energias foton (wl_nm esta en orden DESCENDENTE, por lo
    // que photonE queda en orden ASCENDENTE, como requiere G4).
    G4double photonE[nEm], spectrum[nEm];
    for (G4int i = 0; i < nEm; ++i) {
        photonE[i] = hc / (wl_nm[i] * nm);
        spectrum[i] = relOut[i];
    }

    // Optical properties of EJ-200
    const G4int nOpt = 4;
    G4double eOpt[nOpt]  = {2.0*eV, 2.6*eV, 3.1*eV, 4.0*eV};
    G4double rIdx[nOpt]  = {1.58,   1.58,   1.58,   1.58};
    G4double absL[nOpt]  = {3.8*m,  3.8*m,  3.8*m,  3.8*m};
    //G4double rayl[nOpt]  = {1.5*m,  1.5*m,  1.5*m,  1.5*m};

    // Rayleigh parameterization:
    // L_R(lambda) = L_R(lambdaRef) * (lambda/lambdaRef)^4
    // Choose lambdaRef = 425 nm (EJ-200 emission peak) and
    // start with L_R(425 nm) = 1.5 m as a modeling parameter.
    const G4double lambdaRef = 425.0 * nm;
    const G4double rayleighRef425 = 1.5 * m;

    G4double rayl[nOpt];
    for (G4int i = 0; i < nOpt; ++i) {
        const G4double lambda = hc / eOpt[i];
        rayl[i] = rayleighRef425 * std::pow(lambda / lambdaRef, 4.0);
    }

    auto* mpt = new G4MaterialPropertiesTable();

    // Refractive index, bulk absorption, Rayleigh scattering
    mpt->AddProperty("RINDEX",    eOpt, rIdx, nOpt);
    mpt->AddProperty("ABSLENGTH", eOpt, absL, nOpt);
    mpt->AddProperty("RAYLEIGH",  eOpt, rayl, nOpt);

    // Scintillation (G4 v11+ property names)
    mpt->AddProperty("SCINTILLATIONCOMPONENT1", photonE, spectrum, nEm);
    mpt->AddConstProperty("SCINTILLATIONYIELD",        10000.0 / MeV);
    mpt->AddConstProperty("RESOLUTIONSCALE",           1.0);
    mpt->AddConstProperty("SCINTILLATIONTIMECONSTANT1", 2.1 * ns);
    mpt->AddConstProperty("SCINTILLATIONYIELD1",       1.0);

    mat->SetMaterialPropertiesTable(mpt);
    return mat;
}

// ---------------------------------------------------------------------------
G4Material* CreateEJ230() {
    // EJ-230 is a fast-timing polyvinyltoluene scintillator.  The material is
    // intentionally distinct from the NIST PVT material used by CreateEJ200()
    // so both scintillators can coexist without overwriting each other's MPT.
    G4Material* mat = FindOrBuildPVT("EJ-230", 1.023 * g / cm3);

    // EJ-228/EJ-230 emission spectrum digitized from the Eljen datasheet plot.
    // Peak emission is at 391 nm.  Wavelengths are stored in descending order
    // so the converted photon energies are ascending, as required by Geant4.
    const G4int nEm = 29;
    G4double wl_nm[nEm] = {
        500, 490, 480, 470, 460, 450, 440, 430, 425, 420,
        415, 410, 405, 400, 395, 391, 388, 385, 382, 380,
        378, 375, 372, 370, 365, 360, 355, 350, 345
    };
    G4double relOut[nEm] = {
        0.005, 0.010, 0.020, 0.040, 0.070, 0.115, 0.180, 0.280, 0.350, 0.420,
        0.500, 0.620, 0.750, 0.900, 0.980, 1.000, 0.985, 0.960, 0.900, 0.830,
        0.720, 0.560, 0.380, 0.260, 0.120, 0.050, 0.020, 0.006, 0.000
    };

    const G4double hc = 1239.84193 * eV * nm;

    G4double photonE[nEm], spectrum[nEm];
    for (G4int i = 0; i < nEm; ++i) {
        photonE[i] = hc / (wl_nm[i] * nm);
        spectrum[i] = relOut[i];
    }

    const G4int nOpt = 4;
    G4double eOpt[nOpt] = {2.0*eV, 2.6*eV, 3.1*eV, 4.0*eV};
    G4double rIdx[nOpt] = {1.58, 1.58, 1.58, 1.58};
    G4double absL[nOpt] = {120.0*cm, 120.0*cm, 120.0*cm, 120.0*cm};

    // Keep the same Rayleigh model as EJ-200, referenced to the EJ-230 peak.
    const G4double lambdaRef = 391.0 * nm;
    const G4double rayleighRef391 = 1.5 * m;

    G4double rayl[nOpt];
    for (G4int i = 0; i < nOpt; ++i) {
        const G4double lambda = hc / eOpt[i];
        rayl[i] = rayleighRef391 * std::pow(lambda / lambdaRef, 4.0);
    }

    auto* mpt = new G4MaterialPropertiesTable();
    mpt->AddProperty("RINDEX",    eOpt, rIdx, nOpt);
    mpt->AddProperty("ABSLENGTH", eOpt, absL, nOpt);
    mpt->AddProperty("RAYLEIGH",  eOpt, rayl, nOpt);

    mpt->AddProperty("SCINTILLATIONCOMPONENT1", photonE, spectrum, nEm);
    mpt->AddConstProperty("SCINTILLATIONYIELD",         9700.0 / MeV);
    mpt->AddConstProperty("RESOLUTIONSCALE",            1.0);
    mpt->AddConstProperty("SCINTILLATIONRISETIME1",     0.5 * ns);
    mpt->AddConstProperty("SCINTILLATIONTIMECONSTANT1", 1.5 * ns);
    mpt->AddConstProperty("SCINTILLATIONYIELD1",        1.0);

    mat->SetMaterialPropertiesTable(mpt);
    return mat;
}

// ---------------------------------------------------------------------------
G4Material* CreateSiPMCoupling() {
    // Use SiO2 as the base material and override RINDEX to match the bar.
    // This models a perfect optical-coupling compound between bar and SiPM,
    // eliminating TIR at the bar–SiPM interface (arcsin(1.0/1.58) ≈ 39° → 90°).
    auto* nist = G4NistManager::Instance();
    G4Material* mat = nist->FindOrBuildMaterial("G4_SILICON_DIOXIDE");

    const G4int n = 4;
    G4double e[n] = {2.0*eV, 2.6*eV, 3.1*eV, 4.0*eV};
    G4double r[n] = {1.58,   1.58,   1.58,   1.58};  // matched to EJ-200/EJ-230

    auto* mpt = new G4MaterialPropertiesTable();
    mpt->AddProperty("RINDEX", e, r, n);
    mat->SetMaterialPropertiesTable(mpt);
    return mat;
}

// ---------------------------------------------------------------------------
G4OpticalSurface* CreateBarSurface() {
    // Interfaz barra-aire: dielectric_dielectric polished.
    // Geant4 aplica las ecuaciones de Fresnel automaticamente.
    // Para angulos > arcsin(1/1.58) = 39.3 deg ocurre TIR.
    // No se necesita MPT: el RINDEX de los materiales lo define todo.
    auto* surf = new G4OpticalSurface("BarSurface");
    surf->SetType(dielectric_dielectric);
    surf->SetModel(unified);
    surf->SetFinish(polished);
    surf->SetSigmaAlpha(0.0);
    return surf;
}

// ---------------------------------------------------------------------------
G4OpticalSurface* CreateSiPMSurface() {
    // SiPM detection surface.
    // dielectric_dielectric | polished: photon enters the SiPM volume via
    // Snell's law (no TIR since n_SiPM = n_bar = 1.58 via coupling material).
    // PDE is selected and applied manually in SiPMSD::ProcessHits.

    auto* surf = new G4OpticalSurface("SiPMSurface");
    surf->SetType(dielectric_dielectric);
    surf->SetModel(unified);
    surf->SetFinish(polished);
    surf->SetSigmaAlpha(0.0);

    auto* mpt = new G4MaterialPropertiesTable();
    // No DETECTIONEFFICIENCY here — PDE is applied manually in SiPMSD.
    // The surface is purely optical-contact: polished dielectric_dielectric
    // with n_SiPM = n_bar = 1.58 ensures full transmission (no TIR, no loss).
    surf->SetMaterialPropertiesTable(mpt);
    return surf;
}

// ---------------------------------------------------------------------------
G4Material* CreateMylar() {
    // Mylar (biaxially oriented PET film) used as simplified reflective wrap.
    // With RINDEX = 1.65, the critical angle for total internal reflection at
    // the Mylar–air boundary is arcsin(1/1.65) ≈ 37.3°.  Photons escaping the
    // bar (n=1.58) and entering the Mylar (n=1.65) that then hit the outer
    // Mylar–air interface at shallow angles are totally reflected back, acting
    // as a passive TIR mirror without requiring a G4OpticalSurface on the air.
    auto* nist = G4NistManager::Instance();
    G4Material* mat = nist->FindOrBuildMaterial("G4_MYLAR");

    const G4int n = 4;
    G4double e[n] = {2.0*eV, 2.6*eV, 3.1*eV, 4.0*eV};
    G4double r[n] = {1.65, 1.65, 1.65, 1.65};   // Mylar RINDEX ≈ 1.65

    auto* mpt = new G4MaterialPropertiesTable();
    mpt->AddProperty("RINDEX", e, r, n);
    // Mylar is transparent at optical wavelengths; omit ABSLENGTH so G4 does
    // not apply bulk absorption inside the 25 µm film.
    mat->SetMaterialPropertiesTable(mpt);
    return mat;
}

// ---------------------------------------------------------------------------
G4Material* CreateBlackTape() {
    auto* nist = G4NistManager::Instance();
    G4Material* mat = nist->FindOrBuildMaterial("G4_POLYVINYL_CHLORIDE");

    const G4int n = 4;
    G4double e[n]   = {2.0*eV, 2.6*eV, 3.1*eV, 4.0*eV};
    G4double r[n]   = {1.50,   1.50,   1.50,   1.50};
    G4double abs[n] = {1.0*um, 1.0*um, 1.0*um, 1.0*um};

    auto* mpt = new G4MaterialPropertiesTable();
    mpt->AddProperty("RINDEX",    e, r,   n);
    mpt->AddProperty("ABSLENGTH", e, abs, n);
    mat->SetMaterialPropertiesTable(mpt);
    return mat;
}

