% ---- Appendix G: BLUE statistics ----
\begin{frame}{G1 — BLUE Weight Derivation and Cross-Check}
  \begin{columns}[T]
    \column{0.54\linewidth}
    \textbf{BLUE formula:}
    \[
      w_E = \frac{\sigma_T^2 - C_{ET}}{\sigma_E^2 + \sigma_T^2 - 2C_{ET}}
    \]
    where $\sigma^2 = \sigma_\text{IQR}^2$ and $C_{ET} = \text{Cov}(T_0^E, T_0^T)$ from empirical sample.\\[4pt]
    At $x=0$: $\sigma_E = 53.68\ps$, $\sigma_T = 15.20\ps$, $C_{ET}/(\sigma_E\sigma_T) = 0.16$.
    \[
      w_E = \frac{15.20^2 - C}{53.68^2 + 15.20^2 - 2C} = 0.013
    \]
    \textbf{Formula cross-check:}
    \[
      \sigma_\text{BLUE}^\text{formula} = \sqrt{\frac{\sigma_E^2\sigma_T^2 - C^2}{\sigma_E^2 + \sigma_T^2 - 2C}} = 15.18\ps
    \]
    Event-by-event $\sigma_\text{IQR}[\text{BLUE}] = 15.21\ps$. $\checkmark$ (0.03 ps agreement)

    \column{0.42\linewidth}
    \textbf{G2 — Two variants of $w_E$}\\[4pt]
    \begin{tabular}{p{1.3cm}p{0.9cm}p{1.5cm}}
      \toprule
      Script & $w_E$ & $\sigma^2$ used \\
      \midrule
      best\_est & 0.013 & $\sigma_\text{IQR}^2$ \\
      v5 & 0.086 & np.var() \\
      \bottomrule
    \end{tabular}\\[6pt]
    Both are self-consistent. The difference is whether $\sigma^2$ in the BLUE formula uses IQR-based or empirical variance.\\[4pt]
    \alert{Canonical: $w_E=0.013$} (IQR-based). The IQR metric is the reported resolution, so consistency requires IQR-based weights.\\[4pt]
    The v5 value ($w_E=0.086$) is from np.var() which includes heavy tails. It's physically less clean but not wrong within its own convention.
  \end{columns}
\end{frame}

